SELECT -- 本月数据 COALESCE(SUM(CASE WHEN t_gift.action = '1' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) as monthGiftOutAmount, COALESCE(ROUND((SUM(CASE WHEN t_gift.action = '1' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW()) THEN t_gift.amount ELSE 0 END) - SUM(CASE WHEN t_gift.action = '1' AND MONTH(t_gift.event_time) = MONTH(DATE_SUB(NOW(), INTERVAL 1 MONTH)) AND YEAR(t_gift.event_time) = YEAR(DATE_SUB(NOW(), INTERVAL 1 MONTH)) THEN t_gift.amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN t_gift.action = '1' AND MONTH(t_gift.event_time) = MONTH(DATE_SUB(NOW(), INTERVAL 1 MONTH)) AND YEAR(t_gift.event_time) = YEAR(DATE_SUB(NOW(), INTERVAL 1 MONTH)) THEN t_gift.amount ELSE 0 END), 0) * 100, 2), 0) as monthGiftOutMoM, COALESCE(SUM(CASE WHEN t_gift.action = '2' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) as monthGiftInAmount, COALESCE(ROUND((SUM(CASE WHEN t_gift.action = '2' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW()) THEN t_gift.amount ELSE 0 END) - SUM(CASE WHEN t_gift.action = '2' AND MONTH(t_gift.event_time) = MONTH(DATE_SUB(NOW(), INTERVAL 1 MONTH)) AND YEAR(t_gift.event_time) = YEAR(DATE_SUB(NOW(), INTERVAL 1 MONTH)) THEN t_gift.amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN t_gift.action = '2' AND MONTH(t_gift.event_time) = MONTH(DATE_SUB(NOW(), INTERVAL 1 MONTH)) AND YEAR(t_gift.event_time) = YEAR(DATE_SUB(NOW(), INTERVAL 1 MONTH)) THEN t_gift.amount ELSE 0 END), 0) * 100, 2), 0) as monthGiftInMoM, -- 本月净差额和次数 COALESCE(SUM(CASE WHEN t_gift.action = '2' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN t_gift.action = '1' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) as monthNetAmount, COUNT(CASE WHEN t_gift.action = '1' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN 1 END) as monthGiftOutCount, COUNT(CASE WHEN t_gift.action = '2' AND MONTH(t_gift.event_time) = MONTH(NOW()) AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN 1 END) as monthGiftInCount, -- 上月数据 COALESCE(SUM(CASE WHEN t_gift.action = '1' AND MONTH(t_gift.event_time) = MONTH(DATE_SUB(NOW(), INTERVAL 1 MONTH)) AND YEAR(t_gift.event_time) = YEAR(DATE_SUB(NOW(), INTERVAL 1 MONTH)) THEN t_gift.amount ELSE 0 END), 0) as lastMonthGiftOutAmount, COALESCE(SUM(CASE WHEN t_gift.action = '2' AND MONTH(t_gift.event_time) = MONTH(DATE_SUB(NOW(), INTERVAL 1 MONTH)) AND YEAR(t_gift.event_time) = YEAR(DATE_SUB(NOW(), INTERVAL 1 MONTH)) THEN t_gift.amount ELSE 0 END), 0) as lastMonthGiftInAmount, -- 年度数据 COALESCE(SUM(CASE WHEN t_gift.action = '1' AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) as yearGiftOutAmount, COALESCE(ROUND((SUM(CASE WHEN t_gift.action = '1' AND YEAR(t_gift.event_time) = YEAR(NOW()) THEN t_gift.amount ELSE 0 END) - SUM(CASE WHEN t_gift.action = '1' AND YEAR(t_gift.event_time) = YEAR(NOW()) - 1 THEN t_gift.amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN t_gift.action = '1' AND YEAR(t_gift.event_time) = YEAR(NOW()) - 1 THEN t_gift.amount ELSE 0 END), 0) * 100, 2), 0) as yearGiftOutYoY, COALESCE(SUM(CASE WHEN t_gift.action = '2' AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) as yearGiftInAmount, COALESCE(ROUND((SUM(CASE WHEN t_gift.action = '2' AND YEAR(t_gift.event_time) = YEAR(NOW()) THEN t_gift.amount ELSE 0 END) - SUM(CASE WHEN t_gift.action = '2' AND YEAR(t_gift.event_time) = YEAR(NOW()) - 1 THEN t_gift.amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN t_gift.action = '2' AND YEAR(t_gift.event_time) = YEAR(NOW()) - 1 THEN t_gift.amount ELSE 0 END), 0) * 100, 2), 0) as yearGiftInYoY, -- 年度净差额和次数 COALESCE(SUM(CASE WHEN t_gift.action = '2' AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN t_gift.action = '1' AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN t_gift.amount ELSE 0 END), 0) as yearNetAmount, COUNT(CASE WHEN t_gift.action = '1' AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN 1 END) as yearGiftOutCount, COUNT(CASE WHEN t_gift.action = '2' AND YEAR(t_gift.event_time) = YEAR(NOW())
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
THEN 1 END) as yearGiftInCount, -- 去年数据 COALESCE(SUM(CASE WHEN t_gift.action = '1' AND YEAR(t_gift.event_time) = YEAR(NOW()) - 1 THEN t_gift.amount ELSE 0 END), 0) as lastYearGiftOutAmount, COALESCE(SUM(CASE WHEN t_gift.action = '2' AND YEAR(t_gift.event_time) = YEAR(NOW()) - 1 THEN t_gift.amount ELSE 0 END), 0) as lastYearGiftInAmount, -- 联系人统计 (SELECT COUNT(1) FROM t_contacts_user WHERE is_delete = 0) as totalContacts, (SELECT COUNT(1) FROM t_contacts_user WHERE is_delete = 0 AND MONTH(create_time) = MONTH(NOW()) AND YEAR(create_time) = YEAR(NOW())) as monthNewContacts, (SELECT COUNT(1) FROM t_contacts_user WHERE is_delete = 0 AND YEAR(create_time) = YEAR(NOW())) as yearNewContacts FROM t_personal_gift t_gift WHERE t_gift.is_delete = 0 LIMIT 1

SELECT t_gift.event_name as occasion, COALESCE(SUM(CASE WHEN t_gift.action = '1' THEN t_gift.amount ELSE 0 END), 0) as amount, COUNT(1) as count, ROUND(COUNT(1) / (SELECT COUNT(1) FROM t_personal_gift WHERE is_delete = 0
AND DATE(event_time) BETWEEN #{startTime} AND #{endTime}
) * 100, 2) as percentage, COALESCE(SUM(t_gift.amount), 0) as totalAmount FROM t_personal_gift t_gift WHERE t_gift.is_delete = 0
AND DATE(t_gift.event_time) BETWEEN #{startTime} AND #{endTime}
GROUP BY t_gift.event_name ORDER BY count DESC
